module TopModule (
    input  [2:0] in,
    output [1:0] out
);

    // Population count: count the number of '1's in the 3-bit input.
    // The result fits in 2 bits (0 to 3).
    assign out = {in[1] & in[2], in[0] + in[1] + in[2]};

endmodule

module TopModule (
    input  clk,
    input  resetn,
    input  in,
    output out
);

    // Shift register with four D flops
    // Output 'out' corresponds to the serial output of the last flip-flop
    reg [3:0] shift_reg;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            shift_reg <= 4'b0000;
        end else begin
            shift_reg <= {shift_reg[2:0], in};
        end
    end

    assign out = shift_reg[3];

endmodule

module TopModule (
    input  clk,
    input  reset,
    output [2:0] ena,
    output [15:0] q
);

    // Internal register for the BCD counter (16 bits wide)
    reg [15:0] count;

    // Assign the output ports
    assign q = count;

    // ena[0] is always high (ones digit always increments when not at 9999)
    // ena[1] enables tens digit increment
    // ena[2] enables hundreds digit increment
    // (Thousands digit enable is not strictly required per spec, but we provide it for completeness)
    assign ena = {count[15:12] == 4'd9, count[11:8] == 4'd9, count[7:4] == 4'd9};

    // Synchronous positive-edge-triggered logic with active-high reset
    always @(posedge clk) begin
        if (reset) begin
            count <= 16'd0;
        end else begin
            // BCD increment logic
            // If count is 9999, roll over to 0
            // Otherwise, increment by 1
            if (count == 16'd9999) begin
                count <= 16'd0;
            end else begin
                count <= count + 16'd1;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Assign the complemented outputs for the AND and OR gates
    wire q0_n = ~q0;
    wire q1_n = ~q1;
    wire q2_n = ~q2;

    // D flip-flops with synchronous reset (initial value 0)
    always @(posedge clk) begin
        // The D input for each flip-flop is the XOR of x and its own Q output
        q0 <= x ^ q0;
        q1 <= x ^ q1;
        q2 <= x ^ q2;
    end

    // Three-input NOR gate: output is high only when all inputs are low
    // Inputs: q0, q1, q2 (the flip-flop outputs)
    assign z = ~(q0 | q1 | q2);

endmodule

module TopModule (
    input  [3:0] in,
    output [3:0] out_both,
    output [3:0] out_any,
    output [3:0] out_different
);

    // out_both[i] = in[i] & in[i+1] for i = 0..2; out_both[3] = 1'b0
    assign out_both[0] = in[0] & in[1];
    assign out_both[1] = in[1] & in[2];
    assign out_both[2] = in[2] & in[3];
    assign out_both[3] = 1'b0;

    // out_any[i] = in[i] | in[i-1] for i = 1..3; out_any[0] = 1'b0
    assign out_any[0] = 1'b0;
    assign out_any[1] = in[1] | in[0];
    assign out_any[2] = in[2] | in[1];
    assign out_any[3] = in[3] | in[2];

    // out_different[i] = in[i] ^ in[i-1] for i = 1..3; out_different[0] = in[0] ^ in[3] (wrapping)
    assign out_different[0] = in[0] ^ in[3];
    assign out_different[1] = in[1] ^ in[0];
    assign out_different[2] = in[2] ^ in[1];
    assign out_different[3] = in[3] ^ in[2];

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 4 states to track the sequence 1101
    typedef enum logic [1:0] {
        S_IDLE   = 2'b00,
        S_1      = 2'b01,
        S_11     = 2'b10,
        S_110    = 2'b11
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset, active high)
    always_ff @(posedge clk) begin
        if (reset)
            state <= S_IDLE;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        case (state)
            S_IDLE: begin
                if (data == 1'b1)
                    next_state = S_1;
                else
                    next_state = S_IDLE;
            end
            S_1: begin
                if (data == 1'b1)
                    next_state = S_11;
                else
                    next_state = S_IDLE; // input 0, reset to idle
            end
            S_11: begin
                if (data == 1'b0)
                    next_state = S_110;
                else
                    next_state = S_11; // input 1, stay in S_11 (overlap possibility)
            end
            S_110: begin
                if (data == 1'b1)
                    next_state = S_IDLE; // completed sequence 1101, go to idle
                else
                    next_state = S_IDLE; // input 0, sequence broken
            end
            default: next_state = S_IDLE;
        endcase
    end

    // Output logic: start_shifting is asserted when we enter S_110 (i.e., found 1101)
    // Since reset is active high synchronous, start_shifting stays 1 until reset.
    assign start_shifting = (state == S_110) ? 1'b1 : 1'b0;

endmodule

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output q
);

    // Combinational logic derived from the truth table.
    // The output q is 1 when the following conditions are met:
    //   - d is 1 AND (c is 1 OR b is 1)
    //   - OR (a is 1 AND c is 1 AND d is 1)
    assign q = (d & (c | b)) | (a & c & d);

endmodule

module TopModule (
    input  clk,
    input  L,
    input  q_in,
    input  r_in,
    output Q
);

    // Internal signal to hold the 3-bit state (q[2:0])
    reg [2:0] q;

    always @(posedge clk) begin
        if (L) begin
            // Load mode: shift in r_in as the new MSB
            q <= {r_in, q[2:1]};
        end else begin
            // Shift mode: apply the linear feedback shift register logic
            q <= {q[1] ^ q[2], q[0], q[2]};
        end
    end

    // Output mapping: Q is the LSB of the internal state
    assign Q = q[0];

endmodule

module TopModule (
    input  [3:0] x,
    output f
);

    // Internal signals for each row of the K-map
    // Row 00: x[3:4] = 00
    wire r00_00, r00_01, r00_11, r00_10;
    // Row 01: x[3:4] = 01
    wire r01_00, r01_01, r01_11, r01_10;
    // Row 11: x[3:4] = 11
    wire r11_00, r11_01, r11_11, r11_10;
    // Row 10: x[3:4] = 10
    wire r10_00, r10_01, r10_11, r10_10;

    // Assign the input bits for clarity
    // x[3] is the most significant bit of the address, x[4] is the LSB (based on K-map row order 00,01,11,10)
    // Note: The specification lists x as a 4-bit input [3:0].
    // The K-map rows are ordered as x[3:4] = 00, 01, 11, 10.
    // We will map x[3:4] directly to the row select lines.

    // Row decoding: 
    // Row 00: x[3]==1'b0 && x[4]==1'b0
    // Row 01: x[3]==1'b0 && x[4]==1'b1
    // Row 11: x[3]==1'b1 && x[4]==1'b1
    // Row 10: x[3]==1'b1 && x[4]==1'b0

    // Generate the K-map columns based on x[1:2]
    // Columns: 00, 01, 11, 10
    // x[1] corresponds to the second column bit, x[2] to the first (based on K-map header x[1]x[2])
    // Let's assume x[1] is the most significant column bit and x[2] is the LSB, 
    // matching the standard K-map ordering shown: 00, 01, 11, 10.

    // Column 00: x[1]==1'b0 && x[2]==1'b0
    // Column 01: x[1]==1'b0 && x[2]==1'b1
    // Column 11: x[1]==1'b1 && x[2]==1'b1
    // Column 10: x[1]==1'b1 && x[2]==1'b0

    // Row 00 outputs
    assign r00_00 = (~x[3] & ~x[4] & ~x[1] & ~x[2]); // d
    assign r00_01 = (~x[3] & ~x[4] & ~x[1] &  x[2]);  // 0
    assign r00_11 = (~x[3] & ~x[4] &  x[1] &  x[2]);  // d
    assign r00_10 = (~x[3] & ~x[4] &  x[1] & ~x[2]);  // d

    // Row 01 outputs
    assign r01_00 = (~x[3] &  x[4] & ~x[1] & ~x[2]);  // 0
    assign r01_01 = (~x[3] &  x[4] & ~x[1] &  x[2]);  // d
    assign r01_11 = (~x[3] &  x[4] &  x[1] &  x[2]);  // 1
    assign r01_10 = (~x[3] &  x[4] &  x[1] & ~x[2]);  // 0

    // Row 11 outputs
    assign r11_00 = ( x[3] &  x[4] & ~x[1] & ~x[2]);  // 1
    assign r11_01 = ( x[3] &  x[4] & ~x[1] &  x[2]);  // 1
    assign r11_11 = ( x[3] &  x[4] &  x[1] &  x[2]);  // d
    assign r11_10 = ( x[3] &  x[4] &  x[1] & ~x[2]);  // d

    // Row 10 outputs
    assign r10_00 = ( x[3] & ~x[4] & ~x[1] & ~x[2]);  // 1
    assign r10_01 = ( x[3] & ~x[4] & ~x[1] &  x[2]);  // 1
    assign r10_11 = ( x[3] & ~x[4] &  x[1] &  x[2]);  // d
    assign r10_10 = ( x[3] & ~x[4] &  x[1] & ~x[2]);  // 0

    // Final output logic derived from K-map simplification.
    // f = 1 when:
    // (Row 01 and Col 11) OR
    // (Row 11 and Col 00) OR
    // (Row 11 and Col 01) OR
    // (Row 10 and Col 00) OR
    // (Row 10 and Col 01)
    // Don't cares allow for minimal implementation.

    // Simplified expression derived from the map:
    // f = (x[3] & x[4] & (x[1] | x[2])) | (~x[3] & x[4] & x[1]) | (x[3] & ~x[4] & (x[1] | x[2]))
    // Let's verify this expression against the table.
    // 
    // Case x[3]=0, x[4]=1 (Row 01):
    //   f = (0) | (1 & x[1]) | (0) = x[1]
    //   Table Row 01: 0, d, 1, 0 for cols 00,01,11,10.
    //   If x[1]=0: f=0. Table: 0, d, 1, 0 -> Col 00=0 OK, Col 01=d OK, Col 11=1 (Mismatch if x[1]=0 but x[2]=1? Wait).
    //   Let's re-evaluate the mapping of x[1], x[2] to columns.
    //   K-map header: x[1]x[2] -> 00, 01, 11, 10.
    //   Usually x[1] is MSB of column, x[2] is LSB.
    //   So Col 00: x[1]=0, x[2]=0
    //   Col 01: x[1]=0, x[2]=1
    //   Col 11: x[1]=1, x[2]=1
    //   Col 10: x[1]=1, x[2]=0
    //
    //   Let's re-check the expression f = (x[3] & x[4] & (x[1] | x[2])) | (~x[3] & x[4] & x[1]) | (x[3] & ~x[4] & (x[1] | x[2]))
    //   For Row 01 (~x[3] & x[4]): f = x[1].
    //   If x[1]=0: f=0. This covers Col 00 (0) and Col 10 (0).
    //   If x[1]=1: f=1. This covers Col 01 and Col 11.
    //   Table Row 01: Col 00=0, Col 01=d, Col 11=1, Col 10=0.
    //   Match! (x[1]=0 -> 0,0; x[1]=1 -> d,1).
    //
    //   For Row 11 (x[3] & x[4]): f = x[1] | x[2].
    //   Table Row 11: Col 00=1, Col 01=1, Col 11=d, Col 10=d.
    //   If x[1]=0, x[2]=0: f=0. But Table says 1. Mismatch.
    //   Let's fix the expression for Row 11.
    //   Table Row 11: 1, 1, d, d.
    //   This implies f is always 1 for Row 11 regardless of columns (since don't cares can be used to make it 1, or it's just 1).
    //   So for Row 11, f should be 1.
    //   Let's look at the expression again: (x[3] & x[4] & (x[1] | x[2])). This fails for 00.
    //   Correct expression for Row 11: just 1. i.e., x[3] & x[4].
    //
    //   For Row 10 (x[3] & ~x[4]): f = x[1] | x[2].
    //   Table Row 10: Col 00=1, Col 01=1, Col 11=d, Col 10=0.
    //   If x[1]=0, x[2]=0: f=0. Table says 1. Mismatch.
    //   Correct expression for Row 10: f is 1 for 00, 01 and 0 for 10. d for 11.
    //   This looks like f = x[1] | (~x[2])? No.
    //   Let's list Row 10: 1 (00), 1 (01), d (11), 0 (10).
    //   This is effectively f = ~x[2] | x[1]? No.
    //   Actually, it's f = 1 when x[2]=0, and f = 1 when x[1]=1 & x[2]=1? No.
    //   Let's just use the sum of minterms derived directly from the truth table to be safe, or a verified K-map solver logic.
    //
    //   Let's re-derive carefully.
    //   f = Σm( minterms where f=1 ) + Σd( minterms where f=d )
    //
    //   Minterms (f=1):
    //   Row 01, Col 11: x[3]=0, x[4]=1, x[1]=1, x[2]=1 -> ~x[3] & x[4] & x[1] & x[2]
    //   Row 11, Col 00: x[3]=1, x[4]=1, x[1]=0, x[2]=0 -> x[3] & x[4] & ~x[1] & ~x[2]
    //   Row 11, Col 01: x[3]=1, x[4]=1, x[1]=0, x[2]=1 -> x[3] & x[4] & ~x[1] & x[2]
    //   Row 10, Col 00: x[3]=1, x[4]=0, x[1]=0, x[2]=0 -> x[3] & ~x[4] & ~x[1] & ~x[2]
    //   Row 10, Col 01: x[3]=1, x[4]=0, x[1]=0, x[2]=1 -> x[3] & ~x[4] & ~x[1] & x[2]
    //
    //   Don't Cares (d):
    //   Row 00: all
    //   Row 11, Col 11: x[3]=1, x[4]=1, x[1]=1, x[2]=1 -> x[3] & x[4] & x[1] & x[2]
    //   Row 11, Col 10: x[3]=1, x[4]=1, x[1]=1, x[2]=0 -> x[3] & x[4] & x[1] & ~x[2]
    //   Row 10, Col 11: x[3]=1, x[4]=0, x[1]=1, x[2]=1 -> x[3] & ~x[4] & x[1] & x[2]
    //
    //   Let's simplify the SOP.
    //   Group 1: Row 11. All outputs are 1 or d. We can make them all 1.
    //   So x[3] & x[4] -> f=1. (Covers minterms m12, m13, and d's m15, m14).
    //
    //   Group 2: Row 10, Col 00 and Col 01.
    //   These are x[3] & ~x[4] & ~x[1]. (Covers m8, m9).
    //   The remaining in Row 10 is Col 11 (d) and Col 10 (0).
    //   So Row 10 contributes: x[3] & ~x[4] & ~x[1].
    //
    //   Group 3: Row 01, Col 11.
    //   This is ~x[3] & x[4] & x[1] & x[2]. (Cover m5).
    //   The remaining in Row 01 are Col 00 (0), Col 01 (d), Col 10 (0).
    //   So Row 01 contributes: ~x[3] & x[4] & x[1] & x[2].
    //
    //   Let's check if this covers everything.
    //   f = (x[3] & x[4]) | (x[3] & ~x[4] & ~x[1]) | (~x[3] & x[4] & x[1] & x[2])
    //
    //   Check Row 11 (x[3]&x[4]): f=1. Table: 1, 1, d, d. OK.
    //   Check Row 10 (x[3]&~x[4]):
    //     f = (~x[4] is true) & (~x[1] is true) -> f = ~x[1].
    //     Table Row 10: Col 00 (x[1]=0): f=1. OK. Col 01 (x[1]=0): f=1. OK. Col 11 (x[1]=1): f=0. Table says d. OK (don't care). Col 10 (x[1]=1): f=0. Table says 0. OK.
    //   Check Row 01 (~-x[3]&x[4]):
    //     f = (x[4] is true) & (x[1]&x[2] is true) -> f = x[1] & x[2].
    //     Table Row 01: Col 00 (x[1]=0,x[2]=0): f=0. OK. Col 01 (x[1]=0,x[2]=1): f=0. Table says d. OK. Col 11 (x[1]=1,x[2]=1): f=1. OK. Col 10 (x[1]=1,x[2]=0): f=0. OK.
    //   Check Row 00: Not covered by any term. f=0. Table says d. OK.
    //
    //   The final simplified expression is:
    //   f = (x[3] & x[4]) | (x[3] & ~x[4] & ~x[1]) | (~x[3] & x[4] & x[1] & x[2])
    //
    //   Let's double check the Row 10 logic again.
    //   f = x[3] & ~x[4] & ~x[1].
    //   If x[3]=1, x[4]=0: f = ~x[1].
    //   Columns are x[1]x[2].
    //   Col 00: x[1]=0 -> f=1. Table: 1. OK.
    //   Col 01: x[1]=0 -> f=1. Table: 1. OK.
    //   Col 11: x[1]=1 -> f=0. Table: d. OK.
    //   Col 10: x[1]=1 -> f=0. Table: 0. OK.
    //
    //   Row 01 logic:
    //   f = ~x[3] & x[4] & x[1] & x[2].
    //   If x[3]=0, x[4]=1: f = x[1] & x[2].
    //   Col 00: 0&0=0. Table: 0. OK.
    //   Col 01: 0&1=0. Table: d. OK.
    //   Col 11: 1&1=1. Table: 1. OK.
    //   Col 10: 1&0=0. Table: 0. OK.
    //
    //   Row 11 logic:
    //   f = x[3] & x[4].
    //   If x[3]=1, x[4]=1: f=1.
    //   Col 00: 1. Table: 1. OK.
    //   Col 01: 1. Table: 1. OK.
    //   Col 11: 1. Table: d. OK.
    //   Col 10: 1. Table: d. OK.
    //
    //   Row 00 logic:
    //   f = 0 (implicitly, as no term covers it).
    //   Table: d. OK.
    //
    //   The expression is correct and minimal.

    assign f = (x[3] & x[4]) | (x[3] & ~x[4] & ~x[1]) | (~x[3] & x[4] & x[1] & x[2]);

endmodule

module TopModule (
    input clk,
    input a,
    output [2:0] q
);

    reg [2:0] q_reg;

    always @(posedge clk) begin
        if (a) begin
            case (q_reg)
                3'b000: q_reg <= 3'b001;
                3'b001: q_reg <= 3'b010;
                3'b010: q_reg <= 3'b100;
                3'b100: q_reg <= 3'b000;
                default: q_reg <= 3'b000;
            endcase
        end else begin
            q_reg <= 3'b000;
        end
    end

    assign q = q_reg;

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  in,
    output out
);

    // State encoding: A=2'b00, B=2'b01, C=2'b10, D=2'b11
    reg [1:0] state, next_state;

    // State register (synchronous positive edge-triggered with active high reset)
    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= 2'b00;  // Reset to state A
        else
            state <= next_state;
    end

    // Next-state logic (combinational)
    always @(*) begin
        case (state)
            2'b00: begin // State A
                if (in)
                    next_state = 2'b01; // B
                else
                    next_state = 2'b00; // A
            end
            2'b01: begin // State B
                if (in)
                    next_state = 2'b10; // C
                else
                    next_state = 2'b01; // B
            end
            2'b10: begin // State C
                if (in)
                    next_state = 2'b11; // D
                else
                    next_state = 2'b00; // A
            end
            2'b11: begin // State D
                if (in)
                    next_state = 2'b10; // C
                else
                    next_state = 2'b01; // B
            end
            default: next_state = 2'b00;
        endcase
    end

    // Output logic (Moore machine: output depends only on state)
    assign out = (state == 2'b11) ? 1'b1 : 1'b0;

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  x,
    output z
);

    // State register: 3 bits, synchronous reset
    reg [2:0] y;

    // Next-state logic (combinational)
    always @(*) begin
        case (y)
            3'b000: begin
                if (x)
                    y = 3'b001;
                else
                    y = 3'b000;
            end
            3'b001: begin
                if (x)
                    y = 3'b100;
                else
                    y = 3'b001;
            end
            3'b010: begin
                if (x)
                    y = 3'b001;
                else
                    y = 3'b010;
            end
            3'b011: begin
                if (x)
                    y = 3'b010;
                else
                    y = 3'b001;
            end
            3'b100: begin
                if (x)
                    y = 3'b100;
                else
                    y = 3'b011;
            end
            default: y = 3'b000; // Should never happen
        endcase
    end

    // Output logic (combinational)
    // z = 1 for states 011 and 100
    assign z = (y == 3'b011) || (y == 3'b100);

    // State register update (sequential, positive edge)
    always @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;
        else
            y <= y; // y is updated via the always @(*) block above in simulation,
                    // but for synthesis the MUX/FFs are inferred from the case statement.
                    // The assignment below ensures the flip-flops capture the next state.
                    // Note: In many synthesis flows, the 'y <= y' line is omitted or
                    // the always block is structured as a single always @(posedge clk).
                    // However, to match the "always @(*)" separation style often used
                    // in textbooks, we keep the update here using non-blocking assignments
                    // driven by the next-state mux. To keep it simple and synthesizable
                    // with Icarus Verilog -g2012, we restructure as follows:
    end

    // Recommended synthesizable structure (single always block for clarity):
    // The above separation is kept for readability but the actual register update
    // must be driven by the clock. The following block replaces the register update
    // to ensure correct synthesis with Icarus Verilog.

    always @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;
        else
            case (y)
                3'b000: y <= (x) ? 3'b001 : 3'b000;
                3'b001: y <= (x) ? 3'b100 : 3'b001;
                3'b010: y <= (x) ? 3'b001 : 3'b010;
                3'b011: y <= (x) ? 3'b010 : 3'b001;
                3'b100: y <= (x) ? 3'b100 : 3'b011;
                default: y <= 3'b000;
            endcase
    end

endmodule

module TopModule (
    input  x,
    input  y,
    output z  // <-- Fixed: Added missing output declaration
);

    // ---------- Submodule A (z = (x ^ y) & x) ----------
    // Two instances of A, both with the same inputs tied to the top-level ports
    A a1 (.x(x), .y(y), .z(z_a1));
    A a2 (.x(x), .y(y), .z(z_a2));

    // ---------- Submodule B (behaviour from waveform) ----------
    // Two instances of B, both with the same inputs tied to the top-level ports
    B b1 (.x(x), .y(y), .z(z_b1));
    B b2 (.x(x), .y(y), .z(z_b2));

    // ---------- First OR gate ----------
    // Output of first A ORed with output of first B
    wire or_out;
    assign or_out = z_a1 | z_b1;

    // ---------- Second AND gate ----------
    // Output of second A ANDed with output of second B
    wire and_out;
    assign and_out = z_a2 & z_b2;

    // ---------- Final XOR ----------
    // The XOR of the OR and AND outputs drives 'z'
    assign z = or_out ^ and_out;

endmodule

