                // s is 3 bits: s[2] highest, s[0] lowest.
                // Assertion means water level is at or above that sensor.
                // "Above s[2]" means s[2] is asserted (and presumably s[1], s[0] also asserted if we consider continuity, but spec says "s[0], s[1], s[2]" asserted).
                // "Between s[2] and s[1]" means s[0], s[1] asserted, s[2] not.
                // "Between s[1] and s[0]" means s[0] asserted, s[1] not.
                // "Below s[0]" means none asserted.

                // Let's map sensor patterns to states.
                // Pattern: s[2] s[1] s[0]
                // 1     1     1   -> Above s[2] -> state 11 (0b11)
                // 0     1     1   -> Between s[2] and s[1] -> state 10 (0b10)
                // 0     0     1   -> Between s[1] and s[0] -> state 01 (0b01)
                // 0     0     0   -> Below s[0] -> state 00 (0b00)

                // Note: The specification table lists "Sensors Asserted".
                // For "Between s[2] and s[1]": s[0], s[1] asserted. This implies s[2] is 0.
                // For "Between s[1] and s[0]": s[0] asserted. This implies s[1] is 0.
                // For "Below s[0]": None asserted. s[0]=0.

                // Therefore, the input vector s directly corresponds to the asserted sensors.
                // We can use case statement on s.

                3'b111: state <= 2'b11; // Above s[2]
                3'b011: state <= 2'b10; // Between s[2] and s[1] (s[1]=1, s[0]=1, s[2]=0)
                3'b001: state <= 2'b01; // Between s[1] and s[0] (s[0]=1, s[1]=0, s[2]=0)
                3'b000: state <= 2'b00; // Below s[0]
                default: state <= state; // Hold
            endcase
        end
    end

endmodule

