                BYTE1: begin
                    // Receive second byte
                    next_state <= BYTE2;
                    // Shift left by 8 and insert new byte at MSB
                    shift_reg <= {shift_reg[15:0], in};
                end

                BYTE2: begin
                    // Receive third byte
                    next_state <= BYTE3;
                    shift_reg <= {shift_reg[15:0], in};
                end

                BYTE3: begin
                    // Third byte received: assert done in the NEXT cycle
                    // out_bytes already holds the complete 24-bit message
                    next_state <= IDLE;
                    done       <= 1'b1;
                end
            endcase
        end
    end

    // Output assignment: out_bytes is valid when done is asserted
    // (registered here to match the FSM flow)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            out_bytes <= 24'b0;
        else if (done)
            out_bytes <= shift_reg;
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [2:0] {
        S_WALK_LEFT   = 3'b000,
        S_WALK_RIGHT  = 3'b001,
        S_FALLING     = 3'b010,
        S_DIGGING     = 3'b011,
        S_SPLATTERED  = 3'b100
    } state_t;

    // Outputs
    assign walk_left   = (state == S_WALK_LEFT);
    assign walk_right  = (state == S_WALK_RIGHT);
    assign aaah        = (state == S_FALLING);
    assign digging     = (state == S_DIGGING);

    // Registers
    state_t state, next_state;
    logic [4:0] fall_counter;  // counts up to 31, enough for >20
    state_t walk_dir_saved;    // direction saved before falling/digging

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= S_WALK_LEFT;
            fall_counter <= 0;
            walk_dir_saved <= S_WALK_LEFT;
        end else begin
            state <= next_state;
            // fall_counter updates based on state
            case (state)
                S_FALLING: begin
                    if (fall_counter < 31)
                        fall_counter <= fall_counter + 1;
                end
                default: fall_counter <= fall_counter; // hold
            endcase
        end
    end

    // Next-state logic
    always_comb begin
        // Default next state is current state
        next_state = state;

        case (state)
            S_WALK_LEFT: begin
                // Priority 1: Fall if ground disappears
                if (!ground) begin
                    next_state = S_FALLING;
                    fall_counter <= 0;  // start counting
                    walk_dir_saved <= S_WALK_LEFT;
                end
                // Priority 2: Dig if ground=1 and dig=1
                else if (ground && dig) begin
                    next_state = S_DIGGING;
                    walk_dir_saved <= S_WALK_LEFT;  // save direction before digging
                end
                // Priority 3: Switch direction if bumped
                else begin
                    if (bump_left && !bump_right)
                        next_state = S_WALK_RIGHT;
                    else if (bump_right && !bump_left)
                        next_state = S_WALK_LEFT;  // already walking left, but bump_right while walking left -> walk left (no change? Actually should stay left)
                    else if (bump_left && bump_right)
                        next_state = S_WALK_RIGHT;  // switch directions: left->right
                    // else stay walking left
                end
            end

            S_WALK_RIGHT: begin
                if (!ground) begin
                    next_state = S_FALLING;
                    fall_counter <= 0;
                    walk_dir_saved <= S_WALK_RIGHT;
                end
                else if (ground && dig) begin
                    next_state = S_DIGGING;
                    walk_dir_saved <= S_WALK_RIGHT;
                end
                else begin
                    if (bump_right && !bump_left)
                        next_state = S_WALK_LEFT;
                    else if (bump_left && !bump_right)
                        next_state = S_WALK_RIGHT;  // already walking right
                    else if (bump_left && bump_right)
                        next_state = S_WALK_LEFT;  // switch: right->left
                end
            end

            S_FALLING: begin
                // If ground reappears
                if (ground) begin
                    if (fall_counter > 20) begin
                        // Splatter
                        next_state = S_SPLATTERED;
                    end else begin
                        // Resume walking in saved direction
                        if (walk_dir_saved == S_WALK_LEFT)
                            next_state = S_WALK_LEFT;
                        else
                            next_state = S_WALK_RIGHT;
                    end
                end
                // else stay falling, counter already incremented in register
            end

            S_DIGGING: begin
                // If ground disappears (reaches other side)
                if (!ground) begin
                    next_state = S_FALLING;
                    fall_counter <= 0;
                    walk_dir_saved <= walk_dir_saved;  // keep the saved direction (direction before digging)
                end
                // If ground=1 and dig=1, stay digging
                else if (ground && dig) begin
                    next_state = S_DIGGING;
                end
                // If ground=1 and !dig, stop digging and resume walking in saved direction
                else if (ground && !dig) begin
                    if (walk_dir_saved == S_WALK_LEFT)
                        next_state = S_WALK_LEFT;
                    else
                        next_state = S_WALK_RIGHT;
                end
                // else stay digging (shouldn't happen if ground=1 and dig=1)
            end

            S_SPLATTERED: begin
                // Stay splattered forever (until reset)
                next_state = S_SPLATTERED;
            end
        endcase
    end

endmodule

module TopModule (
    input  [2:0] in,
    output [1:0] out
);

    // Population count implementation
    // Counts the number of '1's in the 3-bit input vector
    // out is 2 bits wide (0 to 3)
    assign out = {in[1] & in[2], in[0] + in[1] + in[2]};

endmodule

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output q
);

    // Combinational logic derived from the provided truth table.
    // The output q is the OR of three AND terms:
    //   (NOT a AND NOT b AND c AND d)
    //   (NOT a AND b AND NOT c)
    //   (a AND b AND c AND d)
    assign q = (~a & ~b & c & d) |
               (~a & b & ~c) |
               (a & b & c & d);

endmodule

module TopModule (
    input  clk,
    input  L,
    input  q_in,
    input  r_in,
    output Q
);

    reg [2:0] q;

    always @(posedge clk) begin
        if (L) begin
            q <= {q[1] ^ q[2], q[0], q_in};
        end else begin
            q <= {q[1] ^ q[2], q[0], r_in};
        end
    end

    assign Q = q[2];

endmodule

module TopModule (
    input  [3:0] x,
    output       f
);

    // Assign the output f based on the K-map specification.
    // The K-map is indexed with x[3]x[4] as rows and x[1]x[2] as columns.
    // Don't-care conditions are treated as 1 for minimal SOP implementation.
    assign f = (~x[3] & ~x[4] & ~x[1]) |          // m1  (x=0001)
               (~x[3] & ~x[4] &  x[1] &  x[2]) | // m3  (x=0011) - d treated as 1
               (~x[3] &  x[4] &  x[1]) |          // m5  (x=0101) - d treated as 1
               ( x[3] & ~x[4] & ~x[1] & ~x[2]) | // m8  (x=1000) - d treated as 1
               ( x[3] & ~x[4] &  x[1] & ~x[2]) | // m10 (x=1010)
               ( x[3] &  x[4] &  x[1] &  x[2]) | // m15 (x=1111) - d treated as 1
               ( x[3] &  x[4] & ~x[1] &  x[2]) | // m13 (x=1101) - d treated as 1
               ( x[3] &  x[4] & ~x[1] & ~x[2]);  // m12 (x=1100) - d treated as 1

endmodule

module TopModule (
    input  logic clk,
    input  logic a,
    output logic [2:0] q
);

    // Internal state register (3 bits)
    logic [2:0] state;

    // State transition logic (sequential always block)
    always_ff @(posedge clk) begin
        case (state)
            3'b000: begin
                if (a)
                    state <= 3'b001;
                else
                    state <= 3'b000;
            end
            3'b001: begin
                if (a)
                    state <= 3'b010;
                else
                    state <= 3'b000;
            end
            3'b010: begin
                if (a)
                    state <= 3'b011;
                else
                    state <= 3'b000;
            end
            3'b011: begin
                if (a)
                    state <= 3'b000;
                else
                    state <= 3'b000;
            end
            default: state <= 3'b000;
        endcase
    end

    // Output logic (combinational always block)
    always_comb begin
        case (state)
            3'b000: q = 3'b000;
            3'b001: q = 3'b100;   // 4
            3'b010: q = 3'b101;   // 5
            3'b011: q = 3'b110;   // 6
            default: q = 3'b000;
        endcase
    end

endmodule

module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic x,
    output logic z
);

    // State assignment: y[2:0] corresponds to the present state in the table
    logic [2:0] y, y_next;

    // Next-state logic (combinational)
    always_comb begin
        case (y)
            3'b000: begin
                y_next = (x == 1'b1) ? 3'b001 : 3'b000;
                z      = 1'b0;
            end
            3'b001: begin
                y_next = (x == 1'b1) ? 3'b100 : 3'b001;
                z      = 1'b0;
            end
            3'b010: begin
                y_next = (x == 1'b1) ? 3'b001 : 3'b010;
                z      = 1'b0;
            end
            3'b011: begin
                y_next = (x == 1'b1) ? 3'b010 : 3'b001;
                z      = 1'b1;
            end
            3'b100: begin
                y_next = (x == 1'b1) ? 3'b100 : 3'b011;
                z      = 1'b1;
            end
            default: begin
                y_next = 3'b000;
                z      = 1'b0;
            end
        endcase
    end

    // Flip-flops (sequential logic, positive edge triggered)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;
        else
            y <= y_next;
    end

    // Output assignment (continuous assignment driven from combinational block)
    // The 'always_comb' block already drives 'z', so this wire declaration is sufficient.
    // Removed the conflicting 'assign z = y[0]' line.

endmodule

module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding
    typedef enum logic [2:0] {
        STATE_A  = 3'b000,
        STATE_B  = 3'b001,
        STATE_C  = 3'b010,
        STATE_D  = 3'b011,
        STATE_E  = 3'b100,
        STATE_F  = 3'b101,
        STATE_G  = 3'b110
    } state_type;

    state_type state, next_state;

    // Outputs registered
    logic f_reg, g_reg;
    assign f = f_reg;
    assign g = g_reg;

    // Next-state logic (combinational)
    always_comb begin
        next_state = state;  // default: stay in current state
        f_reg     = 1'b0;    // default: f low
        g_reg     = 1'b0;    // default: g low

        case (state)
            STATE_A: begin
                // As long as resetn is asserted (low), stay in A.
                // When resetn is de-asserted, after the next clock edge
                // the FSM has to set output f to 1 for one clock cycle.
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                end else begin
                    // De-asserted reset: go to state B, f pulses high next cycle
                    next_state = STATE_B;
                    f_reg      = 1'b1;  // f will be valid after the clock edge
                end
            end

            STATE_B: begin
                // After setting f high in STATE_A, we transition to C.
                // Now monitor x for the sequence 1, 0, 1.
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                    g_reg      = 1'b0;
                end else begin
                    // Sample x
                    if (x == 1'b1) begin
                        // First '1' of the sequence detected
                        next_state = STATE_C;
                    end else begin
                        // Not the expected first '1'; stay in B until we see a 1.
                        next_state = STATE_B;
                    end
                end
            end

            STATE_C: begin
                // We have seen x=1. Now expect x=0.
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                    g_reg      = 1'b0;
                end else begin
                    if (x == 1'b0) begin
                        // Second step: 0 detected, go to state D expecting final 1
                        next_state = STATE_D;
                    end else begin
                        // x is 1 again; reset the sequence (go back to B or A)
                        next_state = STATE_B;
                    end
                end
            end

            STATE_D: begin
                // We have seen 1,0. Now expect x=1 to complete the sequence.
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                    g_reg      = 1'b0;
                end else begin
                    if (x == 1'b1) begin
                        // Sequence 1,0,1 complete -> set g high next cycle
                        next_state = STATE_E;
                        g_reg      = 1'b1;   // g will be valid after clock
                    end else begin
                        // Sequence incomplete; go back to start
                        next_state = STATE_A;
                        f_reg      = 1'b0;
                        g_reg      = 1'b0;
                    end
                end
            end

            // STATE_E: g is high; monitor y within at most two clock cycles
            STATE_E: begin
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                    g_reg      = 1'b0;
                end else begin
                    // Check y
                    if (y == 1'b1) begin
                        // y became 1 within the allowed window -> maintain g=1
                        // Stay in STATE_E indefinitely (until reset)
                        next_state = STATE_E;
                        g_reg      = 1'b1;
                    end else begin
                        // y is 0; we need to count clock cycles.
                        // Transition to STATE_F for the second-cycle check.
                        next_state = STATE_F;
                    end
                end
            end

            STATE_F: begin
                // Second cycle check: if y is 1 now, maintain g.
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                    g_reg      = 1'b0;
                end else begin
                    if (y == 1'b1) begin
                        // y became 1 within the two-cycle window
                        next_state = STATE_E;
                        g_reg      = 1'b1;
                    end else begin
                        // y still 0 after two cycles -> g = 0 permanently
                        next_state = STATE_G;
                        g_reg      = 1'b0;
                    end
                end
            end

            STATE_G: begin
                // g stuck low until reset
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                    g_reg      = 1'b0;
                end else begin
                    next_state = STATE_G;
                    g_reg      = 1'b0;
                end
            end

            default: next_state = STATE_A;
        endcase
    end

    // Sequential logic: state register update on positive edge of clk
    always_ff @(posedge clk or negedge resetn) begin
        if (~resetn) begin
            state <= STATE_A;
            f_reg <= 1'b0;
            g_reg <= 1'b0;
        end else begin
            state <= next_state;
            // f_reg and g_reg are already updated in the combinational block,
            // but we also capture them here to make the pipeline explicit
            // if needed. Since we use non-blocking assignments in the
            // always_comb, the registers update automatically.
        end
    end

endmodule

module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic [2:0] s,
    output logic fr2,
    output logic fr1,
    output logic fr0,
    output logic dfr
);

    // State encoding: 2 bits
    // 2'b00: Below s[0] (all outputs asserted)
    // 2'b01: Between s[1] and s[0] (fr0, fr1)
    // 2'b10: Between s[2] and s[1] (fr0)
    // 2'b11: Above s[2] (no outputs)
    logic [1:0] state, next_state;

    // Combinational logic for next state and output decodings
    always_comb begin
        // Default assignments (stay in current state, outputs hold)
        next_state = state;
        fr0 = 1'b0;
        fr1 = 1'b0;
        fr2 = 1'b0;
        dfr = 1'b0;

        case (state)
            2'b00: begin // Below s[0]
                // All outputs asserted
                fr0 = 1'b1;
                fr1 = 1'b1;
                fr2 = 1'b1;
                dfr = 1'b1;
                // Check if we should transition up
                if (s[0]) begin
                    // If sensor s[0] is asserted, level might be rising.
                    // The spec says transition on "sensor change indicates previous level was lower".
                    // We assume asserting s[0] means level is at or above s[0].
                    next_state = 2'b01;
                end
            end

            2'b01: begin // Between s[1] and s[0]
                fr0 = 1'b1;
                fr1 = 1'b1;
                // Check transitions
                if (s[1]) begin
                    // Level rose to between s[2] and s[1] or above?
                    // If s[1] is asserted and s[2] is not (implied by state), move up.
                    next_state = 2'b10;
                end else if (!s[0]) begin
                    // Level fell below s[0]
                    next_state = 2'b00;
                end
            end

            2'b10: begin // Between s[2] and s[1]
                fr0 = 1'b1;
                // Check transitions
                if (s[2]) begin
                    // Level rose to or above s[2]
                    next_state = 2'b11;
                end else if (!s[1]) begin
                    // Level fell back to between s[1] and s[0]
                    next_state = 2'b01;
                end
            end

            2'b11: begin // Above s[2]
                // No outputs asserted (fr0, fr1, fr2, dfr remain 0)
                // Check transition down
                if (!s[2]) begin
                    // Level fell below s[2]
                    // According to spec, if previous level was higher, we adjust.
                    // Since we were above s[2], previous was higher. 
                    // We drop to between s[2] and s[1].
                    next_state = 2'b10;
                end
            end
        endcase
    end

    // State flip-flops with synchronous reset
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset state: equivalent to long time low (below s[0])
            state <= 2'b00;
        end else begin
            state <= next_state;
        end
    end

endmodule

module TopModule (
    input d,
    input done_counting,
    input ack,
    input [9:0] state,
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

wire [9:0] S = 10'b0000000001;
wire [9:0] S1 = 10'b0000000010;
wire [9:0] S11 = 10'b0000000100;
wire [9:0] S110 = 10'b0000001000;
wire [9:0] B0 = 10'b0000010000;
wire [9:0] B1 = 10'b0000100000;
wire [9:0] B2 = 10'b0001000000;
wire [9:0] B3 = 10'b0010000000;
wire [9:0] Count = 10'b0100000000;
wire [9:0] Wait = 10'b1000000000;

wire [9:0] next_state;

assign next_state[0]  = (!d & state[0]) | (!d & state[2]) | (!d & state[4]);
assign next_state[1]  = (d & state[1]) | (d & state[3]);
assign next_state[2]  = (d & state[3]) | (d & state[1] & !d); // S11 logic
assign next_state[3]  = (state[3] & !d) | (state[3] & d & !state[2]); // S110 logic
assign next_state[4]  = (state[4] & !d) | (state[4] & d & state[2]); // B0 logic
assign next_state[5]  = (state[5] & !done_counting) | (state[7] & !done_counting); // Count logic (simplified)
assign next_state[6]  = (state[6] & done_counting); // Wait logic
assign next_state[7]  = (state[8] & ack); // S logic
assign next_state[8]  = (state[9]); // B3_next derived below
assign next_state[9]  = (state[7] & !ack); // B1 to B2/B2 to B3 chain simplification

// Next-state output assertions
assign S_next  = next_state[0];
assign S1_next = next_state[1];
assign B3_next = next_state[3]; // B3 is index 3 in one-hot (S,S1,S11,S110,B0,B1,B2,B3,Count,Wait)
assign Count_next = next_state[8];
assign Wait_next = next_state[9];

// Output logic (Moore machine - depends only on current state)
assign done = state[9]; // Done asserted in Wait state (index 9)
assign counting = state[8]; // Counting asserted in Count state (index 8)
assign shift_ena = state[3] | state[4] | state[5] | state[6]; // B0, B1, B2, B3 states

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // FSM state encoding
    typedef enum logic [1:0] {
        IDLE    = 2'b00,  // discarding bytes, waiting for in[3]=1
        RECV1   = 2'b01,  // received first byte, expecting second
        RECV2   = 2'b10   // received second byte, expecting third
    } state_t;

    state_t state, next_state;

    // Byte counter: 2 bits (0=first, 1=second, 2=third)
    logic [1:0] byte_cnt;

    // Temporary registers to accumulate the three bytes
    logic [7:0] byte1, byte2, byte3;

    // FSM state transition logic (positive edge triggered, synchronous reset)
    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= IDLE;
            byte_cnt  <= 2'b0;
            out_bytes <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0;          // default: de-asserted

            case (state)
                IDLE: begin
                    if (in[3]) begin
                        // Found byte 1; capture it and move to RECV1
                        byte1 <= in;
                        byte_cnt <= 2'b01; // start counting from 1
                        next_state <= RECV1;
                    end else begin
                        // Keep discarding; stay in IDLE
                        next_state <= IDLE;
                    end
                end

                RECV1: begin
                    // This cycle captures the second byte
                    byte2 <= in;
                    byte_cnt <= 2'b10; // now expecting third byte
                    next_state <= RECV2;
                end

                RECV2: begin
                    // This cycle captures the third byte
                    byte3 <= in;
                    byte_cnt <= 2'b00; // reset counter

                    // Assemble the 24-bit output:
                    // out_bytes[23:16] = first byte
                    // out_bytes[15:8]  = second byte
                    // out_bytes[7:0]   = third byte
                    out_bytes <= {byte1, byte2, byte3};

                    // Assert done in the cycle after the third byte is received
                    done <= 1'b1;

                    // Return to IDLE to start searching for the next message
                    next_state <= IDLE;
                end

                default: next_state <= IDLE;
            endcase
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding: 3 bits
    // 2'b00: WALK_LEFT
    // 2'b01: WALK_RIGHT
    // 2'b10: FALLING
    // 2'b11: DIGGING
    parameter WALK_LEFT   = 2'b00;
    parameter WALK_RIGHT  = 2'b01;
    parameter FALLING     = 2'b10;
    parameter DIGGING     = 2'b11;

    reg [1:0] state;
    reg [4:0] fall_counter; // counts cycles falling (max 31)

    // Output assignments (Moore machine)
    assign walk_left  = (state == WALK_LEFT);
    assign walk_right = (state == WALK_RIGHT);
    assign aaah       = (state == FALLING);
    assign digging    = (state == DIGGING);

    // Asynchronous active-high reset
    always @(posedge areset or posedge clk) begin
        if (areset) begin
            state       <= WALK_LEFT;
            fall_counter <= 5'd0;
        end else begin
            // Default next state is current state
            state       <= state;
            fall_counter <= fall_counter;

            case (state)
                WALK_LEFT: begin
                    // Fall has highest precedence
                    if (!ground) begin
                        state       <= FALLING;
                        fall_counter <= 5'd1;
                    end
                    // Else if ground=1 and dig=1, start digging
                    else if (dig) begin
                        state       <= DIGGING;
                        fall_counter <= 5'd0;
