                        // Since both can be 1, we prioritize bump_left for definiteness.
                        if (bump_left)
                            state <= WALK_RIGHT;
                        else
                            state <= WALK_LEFT; // bump_right
                    end
                    // Else stay walking left
                    fall_counter <= 5'd0;
                end

                WALK_RIGHT: begin
                    if (!ground) begin
                        state       <= FALLING;
                        fall_counter <= 5'd1;
                    end
                    else if (dig) begin
                        state       <= DIGGING;
                        fall_counter <= 5'd0;
                    end
                    else if (bump_left | bump_right) begin
                        if (bump_right)
                            state <= WALK_LEFT;
                        else
                            state <= WALK_RIGHT; // bump_left
                    end
                    fall_counter <= 5'd0;
                end

                FALLING: begin
                    // Increment fall counter
                    fall_counter <= fall_counter + 5'd1;

                    // Check for splatter: if ground=1 and fall_counter > 20
                    if (ground & (fall_counter > 20'd20)) begin
                        // Splatter: all outputs 0 forever
                        state       <= WALK_LEFT; // arbitrary state in "dead" state machine
