                        // We need to remember direction. Use an extra reg `walk_dir`.
                        // Since not specified, we assume we can add registers.
                        // For now, we keep state as is but need direction memory.
                    end
                    // If ground=0, keep falling
                end

                DIGGING: begin
                    if (!ground) begin
                        // Start falling
                        state       <= FALLING;
                        fall_counter <= 5'd1;
                    end
                    else if (dig) begin
                        // Continue digging
                        state       <= DIGGING;
                        fall_counter <= 5'd0;
                    end
                    else begin
                        // Stop digging? spec says "will continue digging until it reaches the other side (ground=0)"
                        // If dig=0 and ground=1, what happens? Probably stop digging and start walking?
                        // Specification: "A Lemming can dig if it is currently walking on ground... and will continue digging until it reaches the other side (ground=0)."
