                        // For simplicity, if dig=0 and ground=1, go to walk left/right? 
                        // We lack direction memory. We'll add a reg `walk_dir`.
                    end
                end
            endcase
        end
    end

    // Additional registers for direction memory and dead state
    reg walk_dir; // 1 = right, 0 = left (memory of walking direction before fall/dig)
    reg dead;    // 1 if splattered

    // Reset logic for extra registers
    always @(posedge areset or posedge clk) begin
        if (areset) begin
            walk_dir <= 1'b0;
            dead     <= 1'b0;
        end else begin
            if (!dead) begin
                // Update walk_dir based on state transitions that set direction
                case (state)
                    WALK_LEFT:  walk_dir <= 1'b0;
                    WALK_RIGHT: walk_dir <= 1'b1;
                    default:    walk_dir <= walk_dir;
                endcase
            end
        end
    end

