module TopModule (
    input  [2:0] in,
    output [1:0] out
);

    // Population count: count the number of '1's in the 3-bit input.
    // The result fits in 2 bits (values 0 to 3).
    assign out = {in[2] + in[1], in[1] + in[0]};

endmodule

module TopModule (
    input  clk,
    input  L,
    input  q_in,
    input  r_in,
    output Q
);

    reg Q_reg;

    always @(posedge clk) begin
        if (L) begin
            Q_reg <= r_in;
        end else begin
            Q_reg <= q_in ^ Q_reg;
        end
    end

    assign Q = Q_reg;

endmodule

module TopModule (
    input  [3:0] x,   // x[3], x[2], x[1], x[0]  (x[1] and x[2] are the K-map row/column select bits)
    output f
);

    // Internal signal to hold the mapped value
    wire f_internal;

    // Mapping:
    // x[3]x[4] in the spec corresponds to the row select (x[3] and x[2] in our 4-bit input)
    // x[1]x[2] in the spec corresponds to the column select (x[1] and x[0] in our 4-bit input)
    //
    // K-map layout (row: x[3]x[2], col: x[1]x[0]):
    //       x[1]x[0]
    // x[3]x[2] 00  01  11  10
    //   00 | d | 0 | d | d |
    //   01 | 0 | d | 1 | 0 |
    //   11 | 1 | 1 | d | d |
    //   10 | 1 | 1 | 0 | d |
    //
    // We implement a minimal SOP expression derived from the map:
    // f = x[3]&x[2]&x[1] | ~x[3]&x[2]&~x[0] | ~x[3]&~x[2]&x[1]&~x[0] | x[3]&~x[2]&x[1]&~x[0]
    //
    // This covers all '1' cells and uses don't-cares to simplify logic.

    assign f_internal = 
        (x[3] & x[2] & x[1]) |
        (~x[3] & x[2] & ~x[0]) |
        (~x[3] & ~x[2] & x[1] & ~x[0]) |
        (x[3] & ~x[2] & x[1] & ~x[0]);

    // Output assignment
    assign f = f_internal;

endmodule

module TopModule (
    input  clk,
    input  a,
    output [2:0] q
);

    // Internal register that holds the current state.
    reg [2:0] q_reg;

    // Assign the output.
    assign q = q_reg;

    // Flip-flop triggered on the rising edge of clk.
    always @(posedge clk) begin
        // Reset-like initialisation: at time 0ns clk=0, a=1, q=x.
        // We initialise q_reg to 0 (which corresponds to the value
        // '4' seen after the first rising edge when a stays 1).
        q_reg <= 3'b000;

        // State machine derived from the simulation table:
        //   a=1, q stays 4 (binary 100) while clk keeps sampling a=1.
        //   a=0, q decrements: 4 -> 5 -> 6 -> 0 -> 1 -> ...
        //   (the values 4,5,6,0,1 map to binary 100,101,110,000,001)
        if (a == 1'b1) begin
            // Hold value when a is high (maintain 4 -> 100)
            q_reg <= 3'b100;
        end else begin
            // Sequence when a is low:
            // 4 (100) -> 5 (101) -> 6 (110) -> 0 (000) -> 1 (001) -> ...
            case (q_reg)
                3'b100: q_reg <= 3'b101; // 4 -> 5
                3'b101: q_reg <= 3'b110; // 5 -> 6
                3'b110: q_reg <= 3'b000; // 6 -> 0
                3'b000: q_reg <= 3'b001; // 0 -> 1
                3'b001: q_reg <= 3'b000; // 1 -> 0 (repeats cycle)
                default: q_reg <= 3'b000;
            endcase
        end
    end

endmodule

module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic x,
    output logic z
);

    // State assignment
    logic [2:0] y;       // present state
    logic [2:0] y_next;  // next state

    // Next-state logic (combinational)
    always_comb begin
        case (y)
            3'b000: begin
                if (x == 1'b0)
                    y_next = 3'b000;
                else
                    y_next = 3'b001;
            end
            3'b001: begin
                if (x == 1'b0)
                    y_next = 3'b001;
                else
                    y_next = 3'b100;
            end
            3'b010: begin
                if (x == 1'b0)
                    y_next = 3'b010;
                else
                    y_next = 3'b001;
            end
            3'b011: begin
                if (x == 1'b0)
                    y_next = 3'b001;
                else
                    y_next = 3'b010;
            end
            3'b100: begin
                if (x == 1'b0)
                    y_next = 3'b011;
                else
                    y_next = 3'b100;
            end
            default: y_next = 3'b000; // Should never happen with complete encoding
        endcase
    end

    // Output logic (combinational)
    // z = 1 for states 011 and 100, else 0
    assign z = (y == 3'b011) || (y == 3'b100);

    // Flip-flops (sequential logic, positive edge triggered)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            y <= 3'b000;
        else
            y <= y_next;
    end

endmodule

